// SPDX-License-Identifier: MIT
// Board adapter for UniXNU's boot_progress hooks and sheng's bounded render core.
// No MMIO, mapping changes, worker threads, storage operations or reset policy.
#include <stdint.h>
#include <stddef.h>
#include <stdarg.h>
extern int vsnprintf(char *, size_t, const char *, va_list);
#include <string.h>
#include <pexpert/pexpert.h>
#include <kern/boot_progress.h>
#include "BootProgressCore.h"
#include "BootProgressDisplay.h"
struct bp_core myron_boot_progress_state;
// Writable diagnostic storage survives the VM permission transition.
uint64_t myron_probe_context[16];
volatile uint64_t myron_console_bind_count;
struct bp_display myron_boot_display;
#define display myron_boot_display
static unsigned enabled, busy;
struct myron_mount_slot {
 char phase[BP_COLS], name[BP_COLS];
 uint64_t a, b, events;
 unsigned at;
};
// Last software event per path, not an atomic hardware snapshot or a verdict.
struct myron_mount_slot myron_mount_slots[5];
volatile uint64_t myron_mount_dropped;
static unsigned mount_started, mount_refresh;
// Independent diagnostic rows: do not take the normal console/cache writer lock.
static unsigned irq_busy, irq_refresh, panic_claimed;
volatile uint64_t myron_irq_pc, myron_irq_psr, myron_irq_sp, myron_irq_returns;
volatile uint64_t myron_panic_pc, myron_panic_lr, myron_panic_esr, myron_panic_far;


// 0: console owns framebuffer; 1: drain writer; 2: scanout; 3: release native console.
// Keep boot_progress_active() true after handoff so video/serial hooks continue
// consuming text here rather than falling back to another framebuffer writer.
static unsigned scanout_state;
volatile uint64_t myron_scanout_prepare_calls, myron_scanout_cancel_calls;
volatile int myron_scanout_release_status;
static uint64_t frequency, epoch;
volatile uint64_t myron_boot_progress_irqs;
volatile uint64_t myron_last_user_abort_esr, myron_last_user_abort_far;
volatile uint64_t myron_user_abort_count;
#define MYRON_EXIT_DESCRIPTION_BYTES 800
static char critical_exit_description[MYRON_EXIT_DESCRIPTION_BYTES+1];
static char critical_exit_name[BP_COLS];
static unsigned critical_exit_claimed, critical_exit_ready, critical_exit_bytes;
static unsigned critical_exit_pid, critical_exit_namespace;
static uint64_t critical_exit_code;
static unsigned exit_mach_claimed, exit_mach_ready, exit_mach_exception;
static uint64_t exit_mach_code, exit_mach_subcode;
static struct boot_progress_exit_trace exit_trace_snapshot;
static unsigned exit_trace_claimed, exit_trace_ready, critical_exit_has_description;
static struct boot_progress_user_pac_state user_pac_snapshot;
static unsigned user_pac_claimed, user_pac_ready;

static void append_text(char *out, unsigned *at, const char *s) {
 while (*at < BP_COLS-1 && *s) out[(*at)++] = *s++;
 out[*at] = 0;
}
static void append_hex(char *out, unsigned *at, uint64_t value) {
 static const char hex[] = "0123456789abcdef";
 append_text(out,at,"0x");
 for (int shift=60;shift>=0;shift-=4) {
  char c[2]={hex[(value>>shift)&15],0};append_text(out,at,c);
 }
}
// Width is fixed by the typed telemetry field, keeping rows within 60 columns.
static void append_hex_width(char *out,unsigned *at,uint64_t value,unsigned digits) {
 static const char hex[]="0123456789abcdef";
 append_text(out,at,"0x");
 for(int shift=(int)(digits-1)*4;shift>=0;shift-=4) {
  char c[2]={hex[(value>>shift)&15],0};append_text(out,at,c);
 }
}
static void pac_pair(unsigned row,const char *a,uint64_t av,const char *b,uint64_t bv) {
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,a);append_hex(line,&at,av);
 append_text(line,&at,b);append_hex(line,&at,bv);
 bp_line(&display,row,line,0xffffffff);
}
#include "MyronRebootEvidence.h"
static void draw_user_pac(void) {
 if(!__atomic_load_n(&user_pac_ready,__ATOMIC_ACQUIRE) || !display.bound ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return;
 const struct boot_progress_user_pac_state *s=&user_pac_snapshot;
 unsigned ec=(unsigned)((s->esr>>26)&63);
 const char *title=!s->kind ? "USER PAC: launchd PID 1, first saved state" :
  ec==0x24 ? "USER ABORT: PID 1, first unresolved data" :
  ec==0x20 ? "USER ABORT: PID 1, first unresolved instruction" :
  "USER ABORT: PID 1, first unresolved other";
 bp_line(&display,20,title,0xffff8080);
 pac_pair(21,"PC=",s->pc," LR=",s->lr);
 pac_pair(22,"SP=",s->sp," FP=",s->fp);
 pac_pair(23,"ESR=",s->esr," CPSR=",s->cpsr);
 char line[BP_COLS]={0};unsigned at=0;
 if(s->kind==1) {
  // FAR_RAW is the saved-state field; CODE_ADDR is the address actually
  // delivered after alignment-emulation/PAC classification. ESR is the
  // original handler argument; S_ESR can reflect alignment recovery.
  pac_pair(24,"FAR_RAW=",s->far," CODE_ADDR=",s->exception_address);
  pac_pair(25,"EXC=",s->exception," CODE=",s->exception_code);
  append_text(line,&at,"CACHE_SLIDE(raw)=");append_hex_width(line,&at,s->cache_slide,8);
  append_text(line,&at," ACCESS=");append_hex_width(line,&at,s->fault_type,2);
  append_text(line,&at," FSC=");append_hex_width(line,&at,s->fault_status,2);
  bp_line(&display,26,line,0xffffffff);
  pac_pair(27,"X28=",s->x[28]," S_ESR=",s->saved_esr);
 } else {
  append_text(line,&at,"FAR(raw; validity unknown)=");append_hex(line,&at,s->far);
  bp_line(&display,24,line,0xffffffff);
  at=0;line[0]=0;append_text(line,&at,"INSN(existing copy; 0 may be unread)=");append_hex(line,&at,s->instruction);
  bp_line(&display,25,line,0xffffffff);
  bp_line(&display,26,"Snapshot only; original exception policy retained",0xffffff00);
  at=0;line[0]=0;append_text(line,&at,"X28=");append_hex(line,&at,s->x[28]);
  bp_line(&display,27,line,0xffffffff);
 }
 for(unsigned i=0;i<28;i+=2) {
  char a[6]={'X',(char)('0'+i/10),(char)('0'+i%10),'=',0,0};
  char b[7]={' ','X',(char)('0'+(i+1)/10),(char)('0'+(i+1)%10),'=',0,0};
  pac_pair(30+i/2,a,s->x[i],b,s->x[i+1]);
 }
}
static void record_user_context(const struct boot_progress_user_pac_state *state) {
 if(!enabled || !state || state->pid!=1 ||
    __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&user_pac_claimed,1,__ATOMIC_ACQ_REL))return;
 // Copy only the bounded kernel-owned saved state supplied by sleh.c. Do not
 // retain its pointer, read user memory, inspect keys or claim the panic path.
 user_pac_snapshot=*state;
 __atomic_store_n(&user_pac_ready,1,__ATOMIC_RELEASE);
 draw_user_pac();
}
void boot_progress_user_pac(const struct boot_progress_user_pac_state *state) {
 if(state && state->kind==0)record_user_context(state);
}
void boot_progress_user_abort_context(const struct boot_progress_user_pac_state *state) {
 if(state && state->kind==1)record_user_context(state);
}
// Fallback only: the exiting thread may carry no Mach exception at all.
// Never substitute these scalar codes for a saved EL0 fault location.
void boot_progress_exit_mach(int pid,unsigned exception,uint64_t code,uint64_t subcode) {
 if(!enabled || pid!=1 || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&exit_mach_claimed,1,__ATOMIC_ACQ_REL))return;
 exit_mach_exception=exception;exit_mach_code=code;exit_mach_subcode=subcode;
 __atomic_store_n(&exit_mach_ready,1,__ATOMIC_RELEASE);
}
static void draw_exit_mach(void) {
 if(!__atomic_load_n(&exit_mach_ready,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&user_pac_ready,__ATOMIC_ACQUIRE))return;
 for(unsigned row=20;row<28;++row)bp_line(&display,row,"",0xffffffff);
 bp_line(&display,20,"EXIT MACH: current exit thread; no saved user state",0xffff8080);
 pac_pair(21,"EXC=",exit_mach_exception," CODE=",exit_mach_code);
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,"SUBCODE=");append_hex(line,&at,exit_mach_subcode);
 bp_line(&display,22,line,0xffffffff);
 bp_line(&display,23,"Zero codes may mean no Mach exception was recorded",0xffffff00);
}
void boot_progress_exit_trace(const struct boot_progress_exit_trace *state) {
 if(!enabled || !state || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&exit_trace_claimed,1,__ATOMIC_ACQ_REL))return;
 // Only copy the caller's bounded kernel-owned array; no user reads here.
 exit_trace_snapshot=*state;
 if(exit_trace_snapshot.count>BOOT_PROGRESS_EXIT_FRAMES)
  exit_trace_snapshot.count=BOOT_PROGRESS_EXIT_FRAMES;
 __atomic_store_n(&exit_trace_ready,1,__ATOMIC_RELEASE);
}
static void draw_exit_trace(void) {
 const struct boot_progress_exit_trace *s=&exit_trace_snapshot;
 for(unsigned row=20;row<28;++row)bp_line(&display,row,"",0xffffffff);
 bp_line(&display,20,"SIGABRT: PID 1 exiting thread user backtrace",0xffff8080);
 pac_pair(21,"CACHE_SLIDE(raw)=",s->cache_slide," COUNT=",s->count);
 pac_pair(22,"READ_ERROR=",(uint64_t)(unsigned)s->error," FLAGS=",s->flags);
 bp_line(&display,23,"BT00 = saved PC; others = return addresses",0xffffffff);
 bp_line(&display,24,"Exit site only; signal sender not established",0xffffff00);
 bp_line(&display,25,"Partial/empty trace is valid when reads fail",0xffffff00);
 for(unsigned row=30;row<44;++row)bp_line(&display,row,"",0xffffffff);
 for(unsigned i=0;i<s->count;i+=2) {
  char a[6]={'B','T',(char)('0'+i/10),(char)('0'+i%10),'=',0};
  char b[7]={' ','B','T',(char)('0'+(i+1)/10),(char)('0'+(i+1)%10),'=',0};
  if(i+1<s->count)pac_pair(30+i/2,a,s->frames[i],b,s->frames[i+1]);
  else {
   char line[BP_COLS]={0};unsigned at=0;
   append_text(line,&at,a);append_hex(line,&at,s->frames[i]);
   bp_line(&display,30+i/2,line,0xffffffff);
  }
 }
}
// Fatal process reason is an already validated kernel-owned string. Copy once,
// before panic: no varargs formatter, user memory access, locks or allocation.
static void draw_exit_reason(void) {
 if(!__atomic_load_n(&critical_exit_ready,__ATOMIC_ACQUIRE) || !display.bound ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return;
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,"CRITICAL EXIT: ");append_text(line,&at,critical_exit_name);
 if(critical_exit_bytes==MYRON_EXIT_DESCRIPTION_BYTES)append_text(line,&at," [800-byte limit]");
 bp_line(&display,28,line,0xffff8080);
 at=0;line[0]=0;append_text(line,&at,"namespace=");append_hex(line,&at,critical_exit_namespace);
 append_text(line,&at," code=");append_hex(line,&at,critical_exit_code);
 bp_line(&display,29,line,0xffff8080);
 if(critical_exit_pid==1 && (critical_exit_namespace==2 || critical_exit_namespace==28) &&
    __atomic_load_n(&user_pac_ready,__ATOMIC_ACQUIRE)) {draw_user_pac();return;}
 if(critical_exit_pid==1 && critical_exit_namespace==2 && critical_exit_code==6 &&
    !critical_exit_has_description && __atomic_load_n(&exit_trace_ready,__ATOMIC_ACQUIRE)) {
  draw_exit_trace();return;
 }
 if(critical_exit_pid==1 && critical_exit_namespace==2)draw_exit_mach();
 unsigned cols=display.width/(6*display.scale);
 if(cols>96)cols=96;
 if(!cols)return;
 // Fourteen rows fit the complete 800-byte cap at minimum supported geometry.
 unsigned offset=0;
 for(unsigned row=30;row<44;++row) {
  unsigned n=0;
  while(n<cols && offset<critical_exit_bytes)line[n++]=critical_exit_description[offset++];
  line[n]=0;bp_line(&display,row,line,0xffffffff);
 }
}
void boot_progress_exit_reason(int pid,const char *name,unsigned ns,uint64_t code,const char *description) {
 if(!enabled || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&critical_exit_claimed,1,__ATOMIC_ACQ_REL))return;
 critical_exit_pid=(unsigned)pid;critical_exit_namespace=ns;critical_exit_code=code;
 critical_exit_has_description=description && description[0];
 bp_copy(critical_exit_name,name ? name : "(unnamed)");
 const char *input=description ? description : "(no exit reason description)";
 unsigned n=0;
 while(n<MYRON_EXIT_DESCRIPTION_BYTES && input[n]) {
  unsigned char c=(unsigned char)input[n];
  critical_exit_description[n++]=c=='\n' || c=='\r' || c=='\t' ? ' ' : c>=32 && c<=126 ? (char)c : '?';
 }
 critical_exit_description[n]=0;critical_exit_bytes=n;
 if(__atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE))return;
 __atomic_store_n(&critical_exit_ready,1,__ATOMIC_RELEASE);draw_exit_reason();
}
static unsigned seconds(void) {
 uint64_t t; __asm__ volatile("mrs %0, cntvct_el0":"=r"(t));
 return frequency ? (unsigned)((t-epoch)/frequency) : 0;
}
// Claim before platform hooks and before formatting. No waiting, allocation,
// MMIO reads, storage or scheduler calls. Nested faults cannot recurse here.
static int claim_panic(void) {
 if(!enabled || !display.bound || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return 0;
 return !__atomic_exchange_n(&panic_claimed,1,__ATOMIC_ACQ_REL);
}
static void render_fault(const char *message,uint64_t pc,uint64_t lr,uint64_t esr,uint64_t far) {
 myron_panic_pc=pc;myron_panic_lr=lr;myron_panic_esr=esr;myron_panic_far=far;
 if(__atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return;
 char line[BP_COLS]={0};unsigned at=0;
 // Publish numeric evidence first in case a corrupt panic message itself faults.
 append_text(line,&at,"PC=");append_hex(line,&at,pc);
 append_text(line,&at," LR=");append_hex(line,&at,lr);
 bp_line(&display,46,line,0xffff4040);
 at=0;line[0]=0;append_text(line,&at,"ESR=");append_hex(line,&at,esr);
 append_text(line,&at," FAR=");append_hex(line,&at,far);
 bp_line(&display,47,line,0xffff4040);
 at=0;line[0]=0;append_text(line,&at,"EARLY PANIC: ");
 append_text(line,&at,message ? message : "(no format string)");
 bp_line(&display,45,line,0xffff4040);
 draw_exit_reason();
 if(!__atomic_load_n(&critical_exit_ready,__ATOMIC_ACQUIRE))draw_user_pac();
}
void myron_boot_progress_fault(const char *message,uint64_t pc,uint64_t lr,uint64_t esr,uint64_t far) {
 if(claim_panic())render_fault(message,pc,lr,esr,far);
}
void myron_boot_progress_panic(const char *format,uint64_t caller) {
 // For an ordinary panic PC is the caller, LR is zero; ESR/FAR are not inferred.
 myron_boot_progress_fault(format,caller,0,0,0);
}

// Last failed factory only: diagnostic correlation, not proof of causation.
// No object pointers or entitlement contents are retained or dereferenced.
struct myron_object_failure {
 uint64_t requested, caller, count;
 unsigned kind, stage;
};
static struct myron_object_failure object_failure;
static unsigned object_failure_busy;
void myron_boot_object_failure(unsigned kind,unsigned stage,uint64_t requested,uint64_t caller) {
 if(!enabled || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&object_failure_busy,1,__ATOMIC_ACQ_REL))return;
 if(!__atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE)) {
  object_failure.kind=kind;object_failure.stage=stage;
  object_failure.requested=requested;object_failure.caller=caller;++object_failure.count;
 }
 __atomic_store_n(&object_failure_busy,0,__ATOMIC_RELEASE);
}
static void draw_object_failure(void) {
 if(__atomic_exchange_n(&object_failure_busy,1,__ATOMIC_ACQ_REL)) {
  bp_line(&display,10,"OBJECT FAILURE: snapshot busy; unavailable",0xffffff00);return;
 }
 struct myron_object_failure s=object_failure;
 __atomic_store_n(&object_failure_busy,0,__ATOMIC_RELEASE);
 bp_line(&display,10,s.count ? "LAST OBJECT FAILURE (may be unrelated)" :
  "No recorded object factory failure",0xffffff00);
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,"kind=");append_hex_width(line,&at,s.kind,2);
 append_text(line,&at," stage=");append_hex_width(line,&at,s.stage,2);
 append_text(line,&at," size/bits=");append_hex(line,&at,s.requested);
 bp_line(&display,11,line,0xffffffff);
 at=0;line[0]=0;append_text(line,&at,"caller=");append_hex(line,&at,s.caller);
 append_text(line,&at," count=");append_hex(line,&at,s.count);
 bp_line(&display,12,line,0xffffffff);
 bp_line(&display,13,"1=dict 2=array 3=string 4=data 5=number; stage 1=alloc 2=init",0xffffffff);
}
void myron_boot_progress_panic_formatted(const char *format,uint64_t caller,va_list *args) {
 if(!claim_panic())return;
 // Retain numeric and literal fallback before any format or %s dereference.
 render_fault(format,caller,0,0,0);
 if(reboot_visible())draw_reboot();else draw_object_failure();
 if(!format || !args)return;
 char message[512];va_list copy;
 va_copy(copy,*args);
 int result=vsnprintf(message,sizeof(message),format,copy);
 va_end(copy);
 message[sizeof(message)-1]=0;
 if(result<0) {
  bp_line(&display,0,"PANIC DETAIL: formatter failed; see literal below",0xffff4040);return;
 }
 bp_line(&display,0,(unsigned)result>=sizeof(message) ?
  "PANIC DETAIL [truncated at 511 bytes]" : "PANIC DETAIL (formatted)",0xffff4040);
 unsigned cols=display.scale ? display.width/(6*display.scale) : 0;
 if(cols>BP_COLS-1)cols=BP_COLS-1;
 if(!cols)return;
 unsigned offset=0;
 // Nine rows cover 511 bytes at the minimum supported 60-column geometry.
 for(unsigned row=1;row<=9;++row) {
  char line[BP_COLS]={0};unsigned n=0;
  while(n<cols && message[offset]) {
   unsigned char c=(unsigned char)message[offset++];
   line[n++]=c>=32 && c<=126 ? (char)c : ' ';
  }
  bp_line(&display,row,line,0xffff8080);
 }
}
// Bounded software history. Values are copied by the typed vfs_bio hook; the
// recorder never dereferences a buffer, walks a stack or waits for a writer.
// IDs: 1 getblk, 2 biodone, 3 valid brelse, 4 alloc, 5 free, 6 geteblk;
// 7 ownership callback, 8 filter callback (address is callback target); 255 failure.
#define MYRON_BUFFER_HISTORY 256
struct myron_buffer_sample {
 uint64_t pointer, caller, block, sequence;
 unsigned kind, flags, lflags, queue;
};
static struct myron_buffer_sample buffer_history[MYRON_BUFFER_HISTORY];
static unsigned buffer_busy;
static uint64_t buffer_sequence, buffer_dropped;
static void buffer_state_line(unsigned row,const struct myron_buffer_sample *v) {
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,"Q=");append_hex(line,&at,v->queue);
 append_text(line,&at," LF=");append_hex(line,&at,v->lflags);
 append_text(line,&at," F=");append_hex(line,&at,v->flags);
 bp_line(&display,row,line,0xffff8080);
}
void myron_buffer_event(unsigned kind,uint64_t pointer,uint64_t caller,
 unsigned queue,unsigned lflags,unsigned flags,uint64_t block) {
 if(!enabled || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE))return;
 unsigned locked=!__atomic_exchange_n(&buffer_busy,1,__ATOMIC_ACQUIRE);
 if(!locked)__atomic_fetch_add(&buffer_dropped,1,__ATOMIC_RELAXED);
 struct myron_buffer_sample v={pointer,caller,block,0,kind,flags,lflags,queue};
 if(kind!=255) {
  if(locked) {
   v.sequence=++buffer_sequence;
   buffer_history[(v.sequence-1)%MYRON_BUFFER_HISTORY]=v;
   __atomic_store_n(&buffer_busy,0,__ATOMIC_RELEASE);
  }
  return;
 }
 if(claim_panic()) {
  render_fault("buf_brelse ownership; PC=release caller",caller,0,0,0);
  if(__atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE)) {
   if(locked)__atomic_store_n(&buffer_busy,0,__ATOMIC_RELEASE);
   return;
  }
  char line[BP_COLS]={0};unsigned at=0;
  append_text(line,&at,"BUFFER=");append_hex(line,&at,pointer);
  append_text(line,&at," BLOCK=");append_hex(line,&at,block);
  bp_line(&display,28,line,0xffff8080);buffer_state_line(29,&v);
  at=0;line[0]=0;append_text(line,&at,"History dropped=");
  append_hex(line,&at,__atomic_load_n(&buffer_dropped,__ATOMIC_RELAXED));
  append_text(line,&at,locked ? " newest first (bounded)" : " writer busy; history omitted");
  bp_line(&display,30,line,0xffffff00);
  // Replace cached mount rows only on a proven buffer invariant failure.
  for(unsigned row=31;row<=43;row++)bp_line(&display,row,"",0xffff8080);
  unsigned shown=0;
  if(locked)for(uint64_t n=buffer_sequence;n && buffer_sequence-n<MYRON_BUFFER_HISTORY && shown<4;--n) {
   const struct myron_buffer_sample *h=&buffer_history[(n-1)%MYRON_BUFFER_HISTORY];
   if(h->sequence!=n || h->pointer!=pointer)continue;
   at=0;line[0]=0;append_text(line,&at,"EVENT=");append_hex(line,&at,h->kind);
   append_text(line,&at,(h->kind==7 || h->kind==8) ? " CALLBACK=" : " CALLER=");append_hex(line,&at,h->caller);
   bp_line(&display,31+shown*3,line,0xff00ffff);
   buffer_state_line(32+shown*3,h);
   at=0;line[0]=0;append_text(line,&at,"SEQ=");append_hex(line,&at,h->sequence);
   append_text(line,&at," BLOCK=");append_hex(line,&at,h->block);
   bp_line(&display,33+shown*3,line,0xffffffff);++shown;
  }
  if(locked && !shown)bp_line(&display,31,"No matching buffer in bounded history",0xffffff00);
 }
 if(locked)__atomic_store_n(&buffer_busy,0,__ATOMIC_RELEASE);
}
void myron_boot_progress_irq_return(void) { ++myron_irq_returns; }
static void draw_irq(unsigned now) {
 if(__atomic_load_n(&critical_exit_ready,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&user_pac_ready,__ATOMIC_ACQUIRE))return;
 if(!display.bound || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE))return;
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,"IRQ PC=");append_hex(line,&at,myron_irq_pc);
 append_text(line,&at," SPSR=");append_hex(line,&at,myron_irq_psr);
 append_text(line,&at,__atomic_load_n(&busy,__ATOMIC_ACQUIRE) ? " console=BUSY" : " console=free");
 bp_line(&display,25,line,0xff80ff80);
