// SPDX-License-Identifier: MIT
// Included by the recorder. Bounded snapshots only; no reset-policy changes.
// Source IDs: 1 authorized BSD syscall, 2 reboot_kernel, 3 host_reboot,
// 4 normal PEHaltRestartInternal. Each path retains its first observation.
static unsigned seconds(void);
struct myron_reboot_request {
 unsigned source, pid, options, details, when;
 uint64_t caller;
 char name[BP_COLS], message[BP_COLS];
};
static struct myron_reboot_request reboot_requests[4];
static unsigned reboot_claimed[4], reboot_ready[4], reboot_first;
static unsigned reboot_history_ready, reboot_history_available;
static char reboot_history[6][BP_COLS], reboot_logs[4][BP_COLS];
static struct boot_progress_exit_trace reboot_trace;
static unsigned reboot_trace_claimed, reboot_trace_ready;
static unsigned shutdown_busy, shutdown_when, reboot_draw_busy;
static uint64_t shutdown_a, shutdown_b, shutdown_events;
static char shutdown_phase[BP_COLS], shutdown_name[BP_COLS];
// launchd's supported launchd_log_serial=1 route writes /dev/console.
// Keep the first three matching messages, before reboot cleanup overwrites the
// short console ring. These are unauthenticated log hints, never a boot verdict.
static char shutdown_log_line[512], shutdown_log_rows[3][2][BP_COLS];
static unsigned shutdown_log_used, shutdown_log_overflow, shutdown_log_count;
static unsigned shutdown_log_times[3];
static unsigned char shutdown_log_lower(unsigned char c) {
 return c>='A' && c<='Z' ? (unsigned char)(c+('a'-'A')) : c;
}
static const char *shutdown_log_find(const char *line,const char *phrase) {
 for(const char *p=line;*p;++p) {
  const char *a=p,*b=phrase;
  while(*a && *b && shutdown_log_lower((unsigned char)*a)==(unsigned char)*b){++a;++b;}
  if(!*b)return p;
 }
 return NULL;
}
static const char *shutdown_log_match(const char *line) {
 static const char *const phrases[]={
  "system reboot initiated by:", "system shutdown initiated by:",
  "userspace reboot initiated by:", "system reboot: flags =",
  "system shutdown: flags =", "legacy shutdown initiated by:",
  "legacy shutdown, caller =", "system shutdown initiated by kernel",
  "critical process crashes:", "rebooting due to ", "rebooting after success",
  "rebooting on exit code:", "committing to system shutdown",
  "could not cleanly tear down userspace", "userspace shutdown timed out:",
  "rebooting now, so the finish-obliteration"
 };
 // This message explicitly says no reboot was requested; don't consume a slot.
 if(shutdown_log_find(line,"feature disabled, device would have rebooted"))return NULL;
 for(unsigned i=0;i<sizeof(phrases)/sizeof(phrases[0]);++i) {
  const char *p=shutdown_log_find(line,phrases[i]);
  if(p)return p;
 }
 return NULL;
}
// Called only under the recorder's existing nonblocking writer lock. Bounded
// static storage; no allocation, I/O, sleep, new locks or printf recursion.
static void shutdown_log_char(char c) {
 if(__atomic_load_n(&reboot_first,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) || shutdown_log_count>=3)return;
 if(c=='\r')return;
 if(c=='\t')c=' ';
 if(c!='\n' && (c<32 || c>126))return;
 if(c!='\n') {
  if(shutdown_log_used<sizeof(shutdown_log_line)-1)shutdown_log_line[shutdown_log_used++]=c;
  else shutdown_log_overflow=1;
  shutdown_log_line[shutdown_log_used]=0;return;
 }
 const char *hit=shutdown_log_match(shutdown_log_line);
 if(hit) {
  unsigned row=shutdown_log_count;
  // A long prefix must not hide the reason. Keep up to 60 preceding bytes.
  const char *begin=shutdown_log_line;
  if(shutdown_log_used>2*(BP_COLS-1) && hit-begin>60)begin=hit-60;
  bp_copy(shutdown_log_rows[row][0],begin);
  unsigned copied=(unsigned)strlen(shutdown_log_rows[row][0]);
  bp_copy(shutdown_log_rows[row][1],begin+copied);
  if(shutdown_log_overflow || strlen(begin)>2*(BP_COLS-1)) {
   char *last=shutdown_log_rows[row][1];unsigned n=(unsigned)strlen(last);
   if(n>=3){last[n-3]='.';last[n-2]='.';last[n-1]='.';}
  }
  shutdown_log_times[row]=seconds();
  __atomic_store_n(&shutdown_log_count,row+1,__ATOMIC_RELEASE);
 }
 shutdown_log_used=0;shutdown_log_overflow=0;shutdown_log_line[0]=0;
}

static int reboot_visible(void) {
 unsigned first=__atomic_load_n(&reboot_first,__ATOMIC_ACQUIRE);
 return first && first<=4 && __atomic_load_n(&reboot_ready[first-1],__ATOMIC_ACQUIRE);
}
static void draw_reboot(void) {
 if(!reboot_visible() || !display.bound || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return;
 if(__atomic_exchange_n(&reboot_draw_busy,1,__ATOMIC_ACQ_REL))return;
 unsigned first=__atomic_load_n(&reboot_first,__ATOMIC_ACQUIRE);
 const struct myron_reboot_request *s=&reboot_requests[first-1];
 bp_line(&display,10,"FIRST REBOOT REQUEST - source is not root-cause proof",0xffffff00);
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,"source=");append_hex_width(line,&at,s->source,2);
 append_text(line,&at," pid=");append_hex_width(line,&at,s->pid,8);
 append_text(line,&at," sec=");append_hex_width(line,&at,s->when,8);
 bp_line(&display,11,line,0xffffffff);
 bp_line(&display,12,s->name,0xffffffff);
 pac_pair(13,"options=",s->options," details=",s->details);
 pac_pair(14,"caller=",s->caller," first=",first);
 unsigned mask=0;uint64_t opts[4]={0};
 for(unsigned i=0;i<4;++i)if(__atomic_load_n(&reboot_ready[i],__ATOMIC_ACQUIRE)) {
  mask|=1U<<i;opts[i]=reboot_requests[i].options;
 }
 pac_pair(15,"BSD=",opts[0]," KERNEL=",opts[1]);
 pac_pair(16,"HOST=",opts[2]," PLATFORM=",opts[3]);
 pac_pair(17,"valid-mask=",mask," 1=BSD 2=K 4=H 8=PE ",0);
 if(!__atomic_exchange_n(&shutdown_busy,1,__ATOMIC_ACQ_REL)) {
  bp_line(&display,18,shutdown_events ? shutdown_phase : "No shutdown phase recorded",0xffffff00);
  bp_line(&display,19,shutdown_name,0xffffffff);
  pac_pair(20,"a=",shutdown_a," b=",shutdown_b);
  pac_pair(21,"events=",shutdown_events," sec=",shutdown_when);
  __atomic_store_n(&shutdown_busy,0,__ATOMIC_RELEASE);
 } else bp_line(&display,18,"Shutdown snapshot busy; last display retained",0xffffff00);
 bp_line(&display,22,"FIRST BSD REQUEST TRACE (not a crash backtrace)",0xff80ffff);
 if(__atomic_load_n(&reboot_trace_ready,__ATOMIC_ACQUIRE)) {
  at=0;line[0]=0;append_text(line,&at,"count=");append_hex_width(line,&at,reboot_trace.count,2);
  append_text(line,&at," flags=");append_hex_width(line,&at,reboot_trace.flags,8);
  append_text(line,&at," error=");append_hex_width(line,&at,(unsigned)reboot_trace.error,8);
  bp_line(&display,23,line,0xffffffff);
  pac_pair(24,"CACHE_SLIDE(raw)=",reboot_trace.cache_slide,"",0);
  for(unsigned i=0;i<8;++i) {
   at=0;line[0]=0;append_text(line,&at,"BT");append_hex_width(line,&at,i,2);
   append_text(line,&at,"=");append_hex(line,&at,i<reboot_trace.count ? reboot_trace.frames[i] : 0);
   bp_line(&display,25+i,line,0xffffffff);
  }
 } else {
  bp_line(&display,23,"No BSD requesting-thread backtrace captured",0xffffffff);
  for(unsigned i=24;i<=32;++i)bp_line(&display,i,"",0xffffffff);
 }
 unsigned log_count=__atomic_load_n(&shutdown_log_count,__ATOMIC_ACQUIRE);
 if(log_count) {
  at=0;line[0]=0;append_text(line,&at,"EARLY SHUTDOWN LOGS (unverified) sec=");
  for(unsigned i=0;i<log_count && i<3;++i) {
   if(i)append_text(line,&at,"/");
   append_hex_width(line,&at,shutdown_log_times[i],8);
  }
  bp_line(&display,33,line,0xffffff00);
  for(unsigned i=0;i<3;++i) {
   bp_line(&display,34+i*2,i<log_count ? shutdown_log_rows[i][0] : "",0xff80ffff);
   bp_line(&display,35+i*2,i<log_count ? shutdown_log_rows[i][1] : "",0xff80ffff);
  }
  unsigned have_history=__atomic_load_n(&reboot_history_ready,__ATOMIC_ACQUIRE) && reboot_history_available;
  for(unsigned i=0;i<3;++i)bp_line(&display,40+i,have_history ? reboot_logs[i] : "",0xffffffff);
 } else if(__atomic_load_n(&reboot_history_ready,__ATOMIC_ACQUIRE) && reboot_history_available) {
  for(unsigned i=0;i<6;++i)bp_line(&display,33+i,reboot_history[i],0xff80ffff);
  for(unsigned i=0;i<4;++i)bp_line(&display,39+i,reboot_logs[i],0xffffffff);
 } else {
  bp_line(&display,33,"Pre-reboot console snapshot unavailable (busy)",0xffffff00);
  for(unsigned i=34;i<=42;++i)bp_line(&display,i,"",0xffffffff);
 }
 bp_line(&display,43,"MESSAGE (kernel copy; empty is normal for reboot):",0xffffff00);
 bp_line(&display,44,s->message,0xffffffff);
 __atomic_store_n(&reboot_draw_busy,0,__ATOMIC_RELEASE);
}
int myron_boot_reboot_request(unsigned source,int pid,const char *name,unsigned options,
 unsigned details,uint64_t caller,const char *message) {
 if(!enabled || source<1 || source>4 || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&reboot_claimed[source-1],1,__ATOMIC_ACQ_REL))return 0;
 struct myron_reboot_request *s=&reboot_requests[source-1];
 s->source=source;s->pid=(unsigned)pid;s->options=options;s->details=details;
 s->caller=caller;s->when=seconds();bp_copy(s->name,name ? name : "(unknown)");
 bp_copy(s->message,message ? message : "");
 __atomic_store_n(&reboot_ready[source-1],1,__ATOMIC_RELEASE);
 unsigned expected=0;
 if(__atomic_compare_exchange_n(&reboot_first,&expected,source,0,__ATOMIC_ACQ_REL,__ATOMIC_ACQUIRE)) {
  if(!__atomic_exchange_n(&busy,1,__ATOMIC_ACQ_REL)) {
   struct bp_core *c=&myron_boot_progress_state;
   unsigned count=c->history_count<6 ? c->history_count : 6;
   for(unsigned i=0;i<count;++i)bp_copy(reboot_history[i],c->history[(c->history_count-count+i)%BP_HISTORY].text);
   count=c->log_lines+1<4 ? c->log_lines+1 : 4;
   for(unsigned i=0;i<count;++i)bp_copy(reboot_logs[i],c->logs[(c->log_row+BP_LOGS+1-count+i)%BP_LOGS]);
   reboot_history_available=1;__atomic_store_n(&busy,0,__ATOMIC_RELEASE);
  }
  __atomic_store_n(&reboot_history_ready,1,__ATOMIC_RELEASE);
 }
 draw_reboot();return 1;
}
void myron_boot_reboot_trace(const struct boot_progress_exit_trace *s) {
 if(!enabled || !s || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&reboot_trace_claimed,1,__ATOMIC_ACQ_REL))return;
 reboot_trace=*s;if(reboot_trace.count>8)reboot_trace.count=8;
 __atomic_store_n(&reboot_trace_ready,1,__ATOMIC_RELEASE);draw_reboot();
}
void myron_boot_shutdown_stage(const char *phase,const char *name,uint64_t a,uint64_t b) {
 if(!enabled || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_exchange_n(&shutdown_busy,1,__ATOMIC_ACQ_REL))return;
 bp_copy(shutdown_phase,phase ? phase : "(unnamed phase)");
 bp_copy(shutdown_name,name ? name : "");shutdown_a=a;shutdown_b=b;
 shutdown_when=seconds();++shutdown_events;
 __atomic_store_n(&shutdown_busy,0,__ATOMIC_RELEASE);draw_reboot();
}

