#!/usr/bin/env python3
"""Verify an extracted native-only CI artifact; does not qualify phone boot."""
import argparse
import hashlib
import json
from pathlib import Path
import struct


def constant_return(data, segments, address, expected):
    """Require the native ABI selector's actual leaf return, not symbol presence."""
    for va, fileoff, filesize in segments:
        if va <= address and address + 16 <= va + filesize:
            at = fileoff + address - va
            words = list(struct.unpack_from('<4I', data, at))
            if words[0] in (0xd503245f, 0xd503201f):  # BTI c / NOP
                words.pop(0)
            if words[:2] not in ([0xd2800000 | (expected << 5), 0xd65f03c0],
                                 [0x52800000 | (expected << 5), 0xd65f03c0]):
                raise ValueError(f'Native PAC selector must return {expected}; actual words {words}')
            return True
    raise ValueError('Native PAC selector is not file-backed')


def direct_calls(data, executable_segments, target):
    """Decode real AArch64 BL instructions in file-backed executable bytes."""
    sites = []
    for va, fileoff, filesize in executable_segments:
        if va % 4 or fileoff % 4 or filesize % 4 or fileoff + filesize > len(data):
            raise ValueError('Invalid executable segment range')
        for offset in range(0, filesize, 4):
            word = struct.unpack_from('<I', data, fileoff + offset)[0]
            if word & 0xfc000000 != 0x94000000:
                continue
            displacement = word & 0x03ffffff
            if displacement & 0x02000000:
                displacement -= 0x04000000
            address = va + offset
            if address + displacement * 4 == target:
                sites.append(address)
    if not sites:
        raise ValueError('No emitted call to required user-fault recorder')
    return sites


def read_address(data, segments, address, length):
    """Read only bytes backed by exactly one segment, never zero-fill a BSS read."""
    matches = [(off + address - va, size) for va, off, size in segments
               if va <= address and address + length <= va + size]
    if len(matches) != 1:
        raise ValueError(f'Expected one file-backed range for {address:#x}+{length}')
    off, _ = matches[0]
    if off < 0 or off + length > len(data):
        raise ValueError('Truncated file-backed range')
    return data[off:off + length]


def decode_function_starts(data, payload, text_base):
    """Decode bounded LC_FUNCTION_STARTS; labels are not function boundaries."""
    at, size = payload
    end = at + size
    if at < 0 or end > len(data):
        raise ValueError('Truncated function-start payload')
    address, starts = text_base, []
    while at < end:
        value = shift = 0
        while True:
            if at >= end or shift >= 64:
                raise ValueError('Invalid function-start ULEB128')
            byte = data[at]
            at += 1
            value |= (byte & 0x7f) << shift
            shift += 7
            if not byte & 0x80:
                break
        if not value:
            if any(data[at:end]):
                raise ValueError('Nonzero data after function-start terminator')
            return starts
        address += value
        if address > 0xffffffffffffffff or address % 4:
            raise ValueError('Invalid function-start address')
        starts.append(address)
    raise ValueError('Missing function-start terminator')


def logical_immediate(word):
    """Decode the ARM logical-immediate bitmask, for MOV via ORR Xd, XZR."""
    width = 64 if word >> 31 else 32
    n, immr, imms = (word >> 22) & 1, (word >> 16) & 63, (word >> 10) & 63
    encoded = (n << 6) | ((~imms) & 63)
    length = encoded.bit_length() - 1
    if length < 1 or (width == 32 and n):
        raise ValueError('Invalid AArch64 logical immediate')
    levels = (1 << length) - 1
    s, r = imms & levels, immr & levels
    if s == levels:
        raise ValueError('Reserved AArch64 logical immediate')
    element_bits = 1 << length
    element_mask = (1 << element_bits) - 1
    bits = (1 << (s + 1)) - 1
    bits = ((bits >> r) | (bits << (element_bits - r))) & element_mask
    return sum(bits << shift for shift in range(0, width, element_bits))


def immediate_x0_before_call(data, segments, start, site):
    """Recover an adjacent compiler-emitted MOV/MOVK constant, not arbitrary code.

    Unknown instructions stop the backward scan. This deliberately rejects
    register loads, intervening calls and unproved data flow instead of guessing.
    """
    instructions = []
    for address in range(site - 4, max(start - 4, site - 36), -4):
        word, = struct.unpack('<I', read_address(data, segments, address, 4))
        if (word & 31) != 0:
            break
        kind = word & 0x7f800000
        if kind in (0x52800000, 0x12800000, 0x72800000):
            instructions.append(word)
            if kind != 0x72800000:
                break
        elif word & 0x7f8003e0 == 0x320003e0:  # ORR immediate, Rn=ZR
            instructions.append(word)
            break
        else:
            break
    value = None
    for word in reversed(instructions):
        width = 64 if word >> 31 else 32
        mask = (1 << width) - 1
        kind = word & 0x7f800000
        shift, imm = ((word >> 21) & 3) * 16, (word >> 5) & 0xffff
        if kind in (0x52800000, 0x12800000, 0x72800000):
            if shift >= width:
                raise ValueError('Invalid wide-move shift')
            if kind == 0x52800000:
                value = imm << shift
            elif kind == 0x12800000:
                value = (~(imm << shift)) & mask
            elif value is not None:
                value = ((value & ~(0xffff << shift)) | (imm << shift)) & mask
        else:
            value = logical_immediate(word)
    if value is None:
        raise ValueError('Cannot prove immediate X0 value at set_tcr call')
    return value


USER_VA_SYMBOLS = {'_gT0Sz', '_gT1Sz', '_pmap_pt_attr_4k',
                   '_pmap_pt_attr_4k_kernel', '_set_tcr', '_arm_vm_init',
                   '_arm_init_cpu', '_arm_init_idle_cpu'}


def verify_user_va(data, segments, executable_segments, symbols, starts):
    """Check scalar geometry and emitted TCR writes, without claiming XNU execution.

    The page_table_attr offsets below are from the pinned XNU header and checked
    by test_myron_user_va_geometry.py against that actual C definition. Pointer
    fields are chained fixups and are deliberately not read as plain addresses.
    """
    if USER_VA_SYMBOLS - symbols.keys():
        raise ValueError(f'Missing user VA43 definitions: {USER_VA_SYMBOLS - symbols.keys()}')
    widths = {}
    for name, expected in (('_gT0Sz', 21), ('_gT1Sz', 26)):
        value, = struct.unpack('<Q', read_address(data, segments, symbols[name], 8))
        if value != expected:
            raise ValueError(f'{name} must be {expected}, got {value}')
        widths[name] = value
    attrs = {}
    for name, level, mask in (('_pmap_pt_attr_4k', 0, 0x7ffffffffff),
                              ('_pmap_pt_attr_4k_kernel', 1, 0x3fffffffff)):
        raw = read_address(data, segments, symbols[name], 120)
        root, commpage, maximum = struct.unpack_from('<III', raw, 64)
        tcr, page, zero, shift, actual_mask = struct.unpack_from('<5Q', raw, 80)
        if (root, commpage, maximum, page, zero, shift, actual_mask) != \
                (level, 1, 3, 4096, 4096, 12, mask):
            raise ValueError(f'Incorrect compiled page-table geometry for {name}')
        if (tcr & 63, (tcr >> 16) & 63) != (21, 26):
            raise ValueError(f'Incorrect compiled TCR widths for {name}')
        # 4K TTBR0 granule=0, TTBR1 granule=2; both translations enabled.
        if ((tcr >> 14) & 3, (tcr >> 30) & 3, (tcr >> 7) & 1, (tcr >> 23) & 1) != (0, 2, 0, 0):
            raise ValueError(f'Incorrect compiled TCR translation controls for {name}')
        attrs[name] = dict(address=hex(symbols[name]), root_level=root,
                           commpage_level=commpage, max_level=maximum, tcr=hex(tcr),
                           page_bytes=page, pagezero_bytes=zero, page_shift=shift,
                           va_valid_mask=hex(actual_mask))
    final = int(attrs['_pmap_pt_attr_4k']['tcr'], 16)
    if final != int(attrs['_pmap_pt_attr_4k_kernel']['tcr'], 16):
        raise ValueError('User and kernel attributes disagree on final TCR')
    if symbols['_pmap_pt_attr_4k'] == symbols['_pmap_pt_attr_4k_kernel']:
        raise ValueError('User and kernel page-table attributes are aliased')
    setter = read_address(data, executable_segments, symbols['_set_tcr'], 16)
    words = list(struct.unpack('<4I', setter))
    if words[0] in (0xd503245f, 0xd503201f):
        words.pop(0)
    if words[:3] != [0xd5182040, 0xd5033fdf, 0xd65f03c0]:
        raise ValueError('set_tcr does not emit the expected MSR TCR_EL1,X0 / ISB / RET')
    calls = direct_calls(data, executable_segments, symbols['_set_tcr'])
    transitions = {}
    for name in ('_arm_vm_init', '_arm_init_cpu', '_arm_init_idle_cpu'):
        begin = symbols[name]
        if begin not in starts:
            raise ValueError(f'{name} is not an emitted function start')
        after = [a for a in starts if a > begin]
        if not after:
            raise ValueError(f'No function boundary after {name}')
        end = min(after)
        sites = [site for site in calls if begin <= site < end]
        if len(sites) != 1:
            raise ValueError(f'Expected one final TCR transition in {name}, got {len(sites)}')
        actual = immediate_x0_before_call(data, executable_segments, begin, sites[0])
        if actual != final:
            raise ValueError(f'{name} passes {actual:#x} to set_tcr instead of {final:#x}')
        transitions[name] = dict(function=hex(begin), call=hex(sites[0]), tcr=hex(actual))
    return dict(runtime_user_va_bits=64 - widths['_gT0Sz'],
                kernel_va_bits=64 - widths['_gT1Sz'], attributes=attrs,
                emitted_final_tcr_transitions=transitions,
                set_tcr_msr_isb_verified=True, geometry_verified=True,
                pointer_selection_verified=False, execution_verified=False,
                limitations=['Compiled scalar geometry and all three emitted final TCR calls are checked.',
                             'Pmap pointer selection and invalid-TTBR0 sequencing are covered by source preflight, not inferred from raw chained pointers.',
                             'This is static machine-code verification, not phone boot or per-CPU runtime observation.'])


def verify(root, require_prelink=False):
    kernels = list(root.rglob('kernel.macho'))
    if len(kernels) != 1:
        raise ValueError('expected exactly one kernel.macho')
    path = kernels[0]
    record = json.loads(path.with_suffix('.json').read_text())
    data = path.read_bytes()
    digest = hashlib.sha256(data).hexdigest()
    if digest != record['candidate_sha256'] or len(data) != record['candidate_bytes']:
        raise ValueError('kernel bytes do not match CI record')
    if record.get('mode') != 'native-only' or record.get('prelink_skipped') is not True:
        raise ValueError('this checker expects the native-only build')
    magic, cpu, subtype, kind, count, size, flags, reserved = struct.unpack_from('<8I', data)
    if (magic, cpu, subtype & 0xffffff, kind) != (0xfeedfacf, 0x100000c, 2, 2):
        raise ValueError('expected arm64e MH_EXECUTE')
    end = 32 + size
    if end > len(data):
        raise ValueError('truncated load commands')
    offset = 32
    symtab = None
    versions = []
    segments = []
    executable_segments = []
    relocation_commands = {}
    function_payload = None
    text_base = None
    for _ in range(count):
        if offset + 8 > end:
            raise ValueError('truncated command header')
        cmd, length = struct.unpack_from('<II', data, offset)
        if length < 8 or offset + length > end:
            raise ValueError('invalid command length')
        if cmd == 2:
            if length != 24 or symtab is not None:
                raise ValueError('invalid symbol table command')
            symtab = struct.unpack_from('<4I', data, offset + 8)
        elif cmd == 0x19:
            va, _, fileoff, filesize = struct.unpack_from('<4Q', data, offset + 24)
            segments.append((va, fileoff, filesize))
            if data[offset + 8:offset + 24].rstrip(b'\0') == b'__TEXT':
                if text_base is not None:
                    raise ValueError('Duplicate __TEXT segment')
                text_base = va
            if struct.unpack_from('<I', data, offset + 60)[0] & 4:
                executable_segments.append((va, fileoff, filesize))
        elif cmd == 0x26:
            if length != 16 or function_payload is not None:
                raise ValueError('Invalid function-start command')
            function_payload = struct.unpack_from('<II', data, offset + 8)
        elif cmd == 0x32:
            if length < 24:
                raise ValueError('invalid build version command')
            platform, minos, sdk, _ = struct.unpack_from('<4I', data, offset + 8)
            versions.append({'platform': platform, 'minimum_os': minos, 'sdk': sdk})
        elif cmd in (0x1e, 0x80000034):
            if length != 16 or cmd in relocation_commands:
                raise ValueError('invalid relocation command')
            start, length_bytes = struct.unpack_from('<II', data, offset + 8)
            if not length_bytes or start + length_bytes > len(data):
                raise ValueError('missing or truncated relocation payload')
            if cmd == 0x1e and data[start] != 0x7f:
                raise ValueError('expected split-segment v2 records')
            relocation_commands[cmd] = length_bytes
        offset += length
    if offset != end or symtab is None:
        raise ValueError('inconsistent load commands or absent symbol table')
    if len(versions) != 1 or versions[0]['platform'] != 2 or versions[0]['minimum_os'] != 27 << 16:
        raise ValueError('expected iPhoneOS 27.0 build version')
    if require_prelink and set(relocation_commands) != {0x1e, 0x80000034}:
        raise ValueError('fileset prelink needs both split-segment v2 and chained fixups; rebuild with XNU_KERNEL_CHAINED_FIXUPS=1')
    so, nsyms, st, strings_size = symtab
    if so + nsyms * 16 > len(data) or st + strings_size > len(data):
        raise ValueError('truncated symbol table')
    strings = data[st:st + strings_size]
    required = {'_source_corecrypto14_original', '_source_corecrypto14_start_once',
                '_source_corecrypto14_bootstrap', '_corecrypto_kext_start',
                '_boot_progress_init', '_boot_progress_stage', '_boot_progress_bind',
                '_boot_progress_putc', '_myron_boot_progress_state',
                '_myron_mount_event', '_myron_mount_slots',
                '_myron_boot_reboot_request', '_myron_boot_reboot_trace', '_myron_boot_shutdown_stage',
                '_myron_buffer_event', '_myron_boot_progress_panic', '_myron_boot_progress_panic_formatted', '_myron_boot_object_failure', '_myron_boot_progress_fault', '_myron_boot_progress_irq_return', '_myron_irq_pc',
                '_boot_progress_user_pac', '_boot_progress_user_abort_context', '_boot_progress_exit_mach', '_boot_progress_exit_trace', '_boot_progress_current_cache_slide',
                '_sysctl__security_mac_lockdown_mode_state_public', '_sysctl_lockdown_mode_state_public',
                '_get_lockdown_mode_state', '_unixnu_kernel_stack_shift', '_PAGE_SHIFT_CONST', '_stack_init', '_ml_default_jop_pid', '_ml_non_arm64e_user_jop_pid'} | USER_VA_SYMBOLS
    found = {}
    undefined = []
    for index in range(nsyms):
        ix, typ, section, desc, value = struct.unpack_from('<IBBHQ', data, so + index * 16)
        if typ & 0xe0 or not ix:
            continue
        if ix >= strings_size:
            raise ValueError('symbol string offset out of bounds')
        stop = strings.find(b'\0', ix)
        if stop < 0:
            raise ValueError('unterminated symbol name')
        name = strings[ix:stop].decode('utf-8', errors='strict')
        if typ & 0xe == 0:
            undefined.append(name)
        if name in required and typ & 0xe == 0xe and section and value:
            found[name] = hex(value)
    if undefined or required - found.keys():
        raise ValueError(f'unresolved symbols {undefined}; missing definitions {required - found.keys()}')
    for name, value in (('_ml_default_jop_pid', 1), ('_ml_non_arm64e_user_jop_pid', 0)):
        constant_return(data, segments, int(found[name], 16), value)
    abort_calls = direct_calls(data, executable_segments, int(found['_boot_progress_user_abort_context'], 16))
    exit_mach_calls = direct_calls(data, executable_segments, int(found['_boot_progress_exit_mach'], 16))
    exit_trace_calls = direct_calls(data, executable_segments, int(found['_boot_progress_exit_trace'], 16))
    exit_slide_calls = direct_calls(data, executable_segments, int(found['_boot_progress_current_cache_slide'], 16))
    formatted_panic_calls = direct_calls(data, executable_segments, int(found['_myron_boot_progress_panic_formatted'], 16))
    object_failure_calls = direct_calls(data, executable_segments, int(found['_myron_boot_object_failure'], 16))
    reboot_calls = {}
    for name, minimum in (('_myron_boot_reboot_request', 4), ('_myron_boot_reboot_trace', 1),
                          ('_myron_boot_shutdown_stage', 4)):
        sites = direct_calls(data, executable_segments, int(found[name], 16))
        if len(sites) < minimum:
            raise ValueError(f'Reboot evidence has too few emitted call sites: {name}: {len(sites)} < {minimum}')
        reboot_calls[name] = [hex(site) for site in sites]
    if function_payload is None or text_base is None:
        raise ValueError('VA43 transition verification requires __TEXT and LC_FUNCTION_STARTS')
    va_geometry = verify_user_va(data, segments, executable_segments,
                                {n: int(a, 16) for n, a in found.items()},
                                decode_function_starts(data, function_payload, text_base))
    return {'native_binary_verified': True, 'sha256': digest, 'bytes': len(data),
            'architecture': 'arm64e', 'cpu_subtype': hex(subtype), 'format': 'MH_EXECUTE',
            'build_versions': versions, 'undefined_symbols': undefined, 'required_definitions': found,
            'continuous_recorder_linked': True,
            'reboot_evidence_calls': reboot_calls,
            'user_abort_recorder_calls': [hex(site) for site in abort_calls],
            'exit_mach_recorder_calls': [hex(site) for site in exit_mach_calls],
            'exit_trace_recorder_calls': [hex(site) for site in exit_trace_calls],
            'exit_slide_accessor_calls': [hex(site) for site in exit_slide_calls],
            'formatted_panic_calls': [hex(site) for site in formatted_panic_calls],
            'object_failure_calls': [hex(site) for site in object_failure_calls],
            'native_pac_selectors_verified': {'arm64e': 1, 'arm64': 0},
            'native_user_va_geometry': va_geometry,
            'split_segment_v2_present': 0x1e in relocation_commands,
            'chained_fixups_present': 0x80000034 in relocation_commands,
            'prelink_verified': False, 'phone_boot_verified': False, 'desktop_reached': False}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('artifact_root', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--require-prelink', action='store_true')
    args = parser.parse_args()
    result = json.dumps(verify(args.artifact_root, args.require_prelink), indent=2) + '\n'
    if args.output:
        args.output.write_text(result)
    print(result, end='')
